arguments.prompt:
Analyze the CSV file at /app/benchmark/data.csv and compute the following statistics. Output ONLY JSON with exact numbers — no commentary, no fabrication. Every number must come from the data.

Parse rules:
- discounted_price, actual_price: remove ₹ and commas, convert to float
- discount_percentage: remove %, convert to float
- rating: convert to float, skip malformed (non-numeric)
- rating_count: remove commas, convert to int, skip missing
- category: split by | to get top-level (index 0)

Compute and return JSON with these exact keys:

{
  "total_products": <int>,
  "avg_rating": <float 2dp>,
  "median_rating": <float 2dp>,
  "avg_discount_pct": <float 2dp>,
  "median_discount_pct": <float 2dp>,
  "median_rating_count": <int>,
  "avg_rating_count": <float 0dp>,
  "high_rating_share": <float 2dp, % of products with rating >= 4.0>,
  "rating_corr_discount": <float 4dp, Pearson correlation between discount_percentage and rating>,
  "rating_count_corr_discount": <float 4dp, Pearson correlation between discount_percentage and rating_count>,
  "rating_distribution": {
    "1.0-1.9": <int count>,
    "2.0-2.9": <int count>,
    "3.0-3.9": <int count>,
    "4.0-4.9": <int count>,
    "5.0": <int count>
  },
  "discount_buckets": {
    "0-20%": {"count": <int>, "avg_rating": <float 2dp>},
    "21-40%": {"count": <int>, "avg_rating": <float 2dp>},
    "41-60%": {"count": <int>, "avg_rating": <float 2dp>},
    "61-80%": {"count": <int>, "avg_rating": <float 2dp>},
    "81-100%": {"count": <int>, "avg_rating": <float 2dp>}
  },
  "price_buckets": {
    "0-500": {"count": <int>, "avg_rating": <float 2dp>, "avg_discount": <float 2dp>},
    "501-2000": {"count": <int>, "avg_rating": <float 2dp>, "avg_discount": <float 2dp>},
    "2001-10000": {"count": <int>, "avg_rating": <float 2dp>, "avg_discount": <float 2dp>},
    "10001+": {"count": <int>, "avg_rating": <float 2dp>, "avg_discount": <float 2dp>}
  },
  "top_categories": [
    {
      "name": <string top-level category>,
      "count": <int>,
      "avg_rating": <float 2dp>,
      "avg_discount": <float 2dp>,
      "avg_rating_count": <float 0dp>,
      "high_rating_share": <float 2dp>
    }
    ... all top-level categories, sorted by count desc
  ],
  "top10_by_rating_count": [
    {"product_name": <first 60 chars>, "category": <top-level>, "rating": <float>, "rating_count": <int>, "discount_pct": <float>}
    ... top 10 products by rating_count
  ],
  "bottom5_categories_by_rating": [
    {"name": <string>, "count": <int>, "avg_rating": <float 2dp>}
    ... bottom 5 top-level categories by avg_rating, min 5 products each
  ],
  "top5_categories_by_rating": [
    {"name": <string>, "count": <int>, "avg_rating": <float 2dp>}
    ... top 5 top-level categories by avg_rating, min 5 products each
  ],
  "review_sentiment": {
    "common_positive_words": [list of 10 most common positive words in review_title],
    "common_negative_words": [list of up to 10 negative/complaint words found in review_title/review_content]
  }
}

Use Python/pandas to compute. Read the file, process it, print the JSON result.

