File created successfully at: /app/output/final_report.html

[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a2b4a;
    --accent: #f59e0b;
    --accent2: #3b82f6;
    --success: #10b981;
    --danger: #ef4444;
    --warn: #f97316;
    --bg: #f8fafc;
    --card: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --muted: #64748b;
    --light: #f1f5f9;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); font-size: 14px; line-height: 1.6; }

  /* Header */
  .report-header { background: linear-gradient(135deg, #1a2b4a 0%, #2d4a7a 100%); color: #fff; padding: 48px 64px 40px; position: relative; overflow: hidden; }
  .report-header::after { content: ''; position: absolute; right: -80px; top: -80px; width: 320px; height: 320px; background: rgba(245,158,11,0.08); border-radius: 50%; }
  .report-header .badge { display: inline-block; background: var(--accent); color: #1a2b4a; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; padding: 4px 12px; border-radius: 20px; margin-bottom: 16px; }
  .report-header h1 { font-size: 30px; font-weight: 700; line-height: 1.25; max-width: 680px; margin-bottom: 10px; }
  .report-header p { color: rgba(255,255,255,0.7); font-size: 14px; max-width: 560px; }
  .report-meta { display: flex; gap: 24px; margin-top: 24px; font-size: 12px; color: rgba(255,255,255,0.55); }
  .report-meta span::before { content: '• '; }
  .report-meta span:first-child::before { content: ''; }

  /* Nav */
  .nav { background: var(--primary); padding: 0 64px; display: flex; gap: 0; border-bottom: 1px solid rgba(255,255,255,0.08); }
  .nav a { color: rgba(255,255,255,0.55); text-decoration: none; padding: 14px 18px; font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; border-bottom: 2px solid transparent; transition: all 0.15s; }
  .nav a:hover { color: #fff; border-bottom-color: var(--accent); }

  /* Layout */
  .container { max-width: 1200px; margin: 0 auto; padding: 0 64px; }
  .section { padding: 48px 0 40px; border-bottom: 1px solid var(--border); }
  .section:last-child { border-bottom: none; }
  .section-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--accent); margin-bottom: 8px; }
  .section-title { font-size: 22px; font-weight: 700; color: var(--primary); margin-bottom: 6px; }
  .section-desc { color: var(--muted); font-size: 13px; max-width: 680px; margin-bottom: 32px; }

  /* KPI grid */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-bottom: 40px; }
  .kpi-card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 20px; position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }
  .kpi-card.blue::before { background: var(--accent2); }
  .kpi-card.green::before { background: var(--success); }
  .kpi-card.orange::before { background: var(--warn); }
  .kpi-card.red::before { background: var(--danger); }
  .kpi-label { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.07em; color: var(--muted); margin-bottom: 10px; }
  .kpi-value { font-size: 28px; font-weight: 800; color: var(--primary); line-height: 1; margin-bottom: 6px; }
  .kpi-sub { font-size: 11px; color: var(--muted); }
  .kpi-trend { font-size: 11px; font-weight: 600; margin-top: 6px; }
  .kpi-trend.up { color: var(--success); }
  .kpi-trend.down { color: var(--danger); }
  .kpi-trend.neutral { color: var(--muted); }

  /* Cards */
  .card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 24px; margin-bottom: 20px; }
  .card-title { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
  .card-sub { font-size: 12px; color: var(--muted); margin-bottom: 20px; }

  /* Grid layouts */
