  /* Recommendation cards */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
  .rec-card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 20px; display: flex; gap: 16px; }
