  .rec-num.accent { background: var(--accent); color: var(--primary); }
  .rec-content h4 { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 6px; }
  .rec-content p { font-size: 12px; color: var(--muted); line-height: 1.6; }
  .rec-data { font-size: 11px; font-weight: 600; color: var(--accent2); margin-top: 8px; }

  /* Sentiment grid */
  .sentiment-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .sentiment-col h4 { font-size: 13px; font-weight: 700; margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }
  .sentiment-col h4 .dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
  .word-cloud { display: flex; flex-wrap: wrap; gap: 8px; }
  .word-chip { padding: 5px 12px; border-radius: 20px; font-size: 12px; font-weight: 600; }

  /* Corr indicator */
  .corr-display { text-align: center; padding: 20px; }
  .corr-value { font-size: 48px; font-weight: 800; line-height: 1; }
  .corr-value.negative { color: var(--danger); }
  .corr-value.neutral { color: var(--muted); }
  .corr-label { font-size: 12px; color: var(--muted); margin-top: 6px; }
